#!/usr/bin/env python3
"""Stage 10 local evidence/archive/commit/tag finalization; no simulation or network."""
import argparse
import base64
import hashlib
import json
import os
import subprocess
import tempfile
import zlib
from datetime import datetime, timezone
from pathlib import Path

REPO = Path('/home/lx/microduck-double-balance/workspace')
STAGE = Path('/home/lx/microduck-double-balance/artifacts/double-balance-stage10')
BASE = '00e34c2038771c5d4ad49fe45dff828c0232e60c'
ORIGIN = 'git@github.com:liuxue-lab/microduck-double-balance.git'
TAG = 'stage-10-complete'
MESSAGE = 'Stage 10: archive zero-PPO replay diagnosis and head-contact audit'
SCRIPT_REL = 'scripts/stage10_finalize.py'
LOCAL_REL = 'docs/audits/stage-10-local-finalization.json'
RUNTIME_SHA = 'b61850afbd6fa0deccb3a23a098a910aae74bc0e9b01cca2ee0634c2d1f6ecfd'
PAYLOAD = ''

def require(ok, message):
    if not ok:
        raise RuntimeError(message)

def sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for block in iter(lambda: f.read(1024*1024), b''): h.update(block)
    return h.hexdigest()

def encoded(value):
    return (json.dumps(value, ensure_ascii=False, indent=2)+'\n').encode()

def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))

def inside(root, rel):
    root, rel = Path(root), Path(rel)
    require(not rel.is_absolute() and '..' not in rel.parts, 'Unsafe relative path: '+str(rel))
    p = root/rel
    require(p.resolve().is_relative_to(root.resolve()), 'Path escapes root: '+str(p))
    require(not any(x.is_symlink() for x in [p, *p.parents]), 'Linked path refused: '+str(p))
    return p

def checked(path, checksum, size=None):
    p = Path(path)
    require(not any(x.is_symlink() for x in [p,*p.parents]), 'Linked evidence refused: '+str(p))
    require(p.is_file(), 'Missing evidence: '+str(p))
    require(size is None or p.stat().st_size==size, 'Size mismatch: '+str(p))
    require(sha(p)==checksum, 'SHA256 mismatch: '+str(p))
    return p

def atomic(path, data):
    path = Path(path)
    require(not path.exists() or path.is_file(), 'Non-file target preserved: '+str(path))
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as f:
        temporary = Path(f.name)
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    try:
        temporary.chmod(0o644)
        temporary.replace(path)
    finally:
        temporary.unlink(missing_ok=True)

def git_bytes(*args):
    return subprocess.check_output(['git','-C',str(REPO),*args])

def git(*args):
    return git_bytes(*args).decode().strip()

def git_paths(*args):
    return {x.decode() for x in git_bytes(*args,'-z').split(b'\0') if x}

def run_git(*args):
    subprocess.run(['git','-C',str(REPO),*args],check=True)

def tagged_commit():
    r = subprocess.run(['git','-C',str(REPO),'show-ref','--verify','--quiet','refs/tags/'+TAG])
    if r.returncode==1: return None
    require(r.returncode==0, 'Cannot inspect local tag')
    require(git('cat-file','-t','refs/tags/'+TAG)=='tag','Existing non-annotated tag preserved')
    return git('rev-parse','refs/tags/'+TAG+'^{commit}')

def runtime():
    rows=read(checked(REPO/'docs/audits/stage-09-runtime-hashes.json',RUNTIME_SHA))
    require(len(rows)==101,'Expected 101 frozen runtime files')
    for rel,h in rows.items(): checked(inside(REPO,rel),h)
    return rows

def verify_evidence(evidence):
    runtime()
    print('Stage10FrozenRuntime=101/101',flush=True)
    counts=[]
    for batch in evidence['batches']:
        root=Path(batch['root'])
        require(root.is_relative_to(STAGE),'Unexpected evidence root')
        rows=read(checked(inside(root,batch['manifest']),batch['manifest_sha256']))
        require(len(rows)==batch['file_count'] and len({r['path'] for r in rows})==len(rows),
                'Manifest count/duplicates: '+str(root))
        for row in rows: checked(inside(root,row['path']),row['sha256'],row['size_bytes'])
        for row in batch['archives']:
            require(Path(row['path']).is_relative_to(STAGE),'Unexpected archive path')
            checked(row['path'],row['sha256'])
        counts.append(dict(batch=batch['batch'],files=len(rows),manifest_sha256=batch['manifest_sha256']))
        print('Stage10Evidence='+batch['batch']+'; files='+str(len(rows))+'; SHA256 PASS',flush=True)
    raw_count=0
    for group in evidence['replay_raw']:
        root=Path(group['root'])
        require(root.is_relative_to(STAGE),'Unexpected raw trace root')
        require(len({r['path'] for r in group['files']})==len(group['files']),'Raw manifest duplicates')
        for row in group['files']:
            checked(inside(root,row['path']),row['sha256'],row['size_bytes'])
            raw_count+=1
    for key in ['checkpoint','dataset','dataset_receipt']:
        row=evidence[key]
        checked(row['path'],row['sha256'])
    print('Stage10ReplayRawFiles='+str(raw_count)+'; retained checkpoint and dataset SHA256 PASS',flush=True)
    return dict(status='LOCAL_EVIDENCE_VERIFIED_BEFORE_COMMIT',source_head=BASE,
        frozen_runtime_files=101,runtime_manifest_sha256=RUNTIME_SHA,
        evidence_manifest_counts=counts,review_files=sum(c['files'] for c in counts),
        review_archives=sum(len(b['archives']) for b in evidence['batches']),replay_raw_files=raw_count,
        retained_primary_sha256=evidence['checkpoint']['sha256'],
        evidence_inventory_sha256=hashlib.sha256(encoded(evidence)).hexdigest(),
        new_ppo_updates=0,simulation_launched=False,network_used=False,push_performed=False,
        cloud_status='OFF_CONFIRMED_BY_USER',cloud_status_basis='User confirmation of prior manual shutdown; no cloud query or action performed by this tool.',
        cloud_data_must_be_preserved=True,full_stage09_cloud_trajectories_returned=False,
        B1_and_C1_original_postcheck_gaps_preserved=True,
        policy_objective='UNMET_NO_NEW_QUALIFIED_POLICY',root_cause='NOT_FULLY_ESTABLISHED',
        publication='COMMIT_TAG_AND_USER_SSH_PUSH_PENDING_AT_CREATION_OF_THIS_RECORD')

def perform(payload, verify_only=False):
    require(REPO.is_dir() and git('rev-parse','--show-toplevel')==str(REPO),'Canonical laptop checkout required')
    require(git('branch','--show-current')=='double-balance','Expected double-balance branch')
    require(git('remote','get-url','--all','origin').splitlines()==[ORIGIN], 'Unexpected origin; not changed')
    require(git('remote','get-url','--push','--all','origin').splitlines()==[ORIGIN], 'Unexpected SSH push URL; not changed')
    rows=payload['files']
    allowed={r['path'] for r in rows}|{SCRIPT_REL,LOCAL_REL}
    require(len(allowed)==len(rows)+2,'Duplicate payload paths')
    require(not (set(runtime())&allowed),'Payload would modify frozen runtime')
    head=git('rev-parse','HEAD')
    already=head!=BASE
    if already:
        require(git('log','-1','--format=%s')==MESSAGE and git('rev-list','--parents','-n','1','HEAD').split()==[head,BASE],
                'Unexpected HEAD; existing work preserved')
        require(git_paths('diff','--name-only',BASE,head)==allowed,'Unexpected paths in existing finalization commit')
    tagged=tagged_commit()
    require(tagged is None or (already and tagged==head),'Conflicting stage-10-complete tag preserved; no force update')
    changed=git_paths('diff','HEAD','--name-only')
    staged=git_paths('diff','--cached','--name-only')
    require(staged<=allowed,'Unrelated staged edits preserved: '+', '.join(sorted(staged-allowed)))
    require(changed<=allowed,'Unrelated tracked edits preserved: '+', '.join(sorted(changed-allowed)))
    desired={}
    for row in rows:
        data=base64.b64decode(row['data'],validate=True)
        require(hashlib.sha256(data).hexdigest()==row['sha256'],'Embedded payload hash mismatch')
        desired[row['path']]=data
    desired[SCRIPT_REL]=Path(__file__).read_bytes()
    # This deterministic record is only written after actual checks below pass.
    report=verify_evidence(payload['evidence'])
    desired[LOCAL_REL]=encoded(report)
    for rel,data in desired.items():
        path=inside(REPO,rel)
        require(not path.exists() or (path.is_file() and path.read_bytes()==data),
                'Existing target differs; preserved: '+rel)
        if rel in staged:
            require(git_bytes('show',':'+rel)==data,'Staged target differs; preserved: '+rel)
        if already:
            require(path.is_file() and git_bytes('show','HEAD:'+rel)==data,
                    'Existing finalization commit/worktree differs: '+rel)
        else:
            require(not git_bytes('ls-tree','HEAD','--',rel),'Payload target already tracked at base: '+rel)
    if verify_only:
        print('Stage10Finalize=VERIFIED_ONLY; no files written, no commit/tag/push',flush=True)
        return None
    if not already:
        for rel,data in desired.items():
            p=inside(REPO,rel)
            if not p.exists(): atomic(p,data)
        require(git('rev-parse','HEAD')==BASE,'HEAD changed during checks; files preserved, no commit')
        runtime()
        run_git('add','--',*sorted(desired))
        require(git_paths('diff','--cached','--name-only')==allowed,'Unexpected index; no commit')
        for rel,data in desired.items():
            require(git_bytes('show',':'+rel)==data,'Index bytes differ; no commit: '+rel)
        run_git('diff','--cached','--check')
        run_git('commit','-m',MESSAGE)
        head=git('rev-parse','HEAD')
        require(git('rev-list','--parents','-n','1','HEAD').split()==[head,BASE], 'Unexpected commit parent; no tag')
        require(git_paths('diff','--name-only',BASE,head)==allowed,'Unexpected committed paths; no tag')
    for rel,data in desired.items():
        require(git_bytes('show','HEAD:'+rel)==data and inside(REPO,rel).read_bytes()==data,
                'Committed/worktree bytes differ; no tag: '+rel)
    require(not git_paths('diff','--cached','--name-only'),'Index not clean; no tag')
    require(not git_paths('diff','HEAD','--name-only'),'Tracked changes after commit; no tag')
    runtime()
    if tagged_commit() is None:
        run_git('tag','-a',TAG,head,'-m',
                'Stage 10: zero-PPO diagnostics and head-contact audit reviewed; original postcheck gaps retained; Stage 08 primary retained; full causality unresolved.')
    require(tagged_commit()==head,'Completion tag mismatch')
    receipt=dict(status='LOCAL_FINALIZATION_COMPLETE_SSH_PUSH_PENDING',created_utc=datetime.now(timezone.utc).isoformat(),
        source_base=BASE,commit=head,annotated_tag=TAG,tag_object=git('rev-parse','refs/tags/'+TAG),branch='double-balance',
        changed_paths=sorted(allowed),technical_review='COMPLETE_WITH_LIMITATIONS',local_finalization_complete=True,
        stage10_complete=False,completion_remaining='USER_SSH_PUSH',policy_objective='UNMET_NO_NEW_QUALIFIED_POLICY',
        new_ppo_updates=0,new_simulation_steps=0,network_used=False,push_performed=False,
        cloud_status='OFF_CONFIRMED_BY_USER',cloud_data_must_be_preserved=True,
        full_stage09_cloud_trajectories_returned=False,B1_and_C1_original_postcheck_gaps_preserved=True)
    output=inside(STAGE,'finalization/'+head+'/finalization-receipt.json')
    # Re-running preserves the first valid receipt and its actual completion timestamp.
    if output.exists():
        old=read(output)
        require({k:v for k,v in old.items() if k!='created_utc'}=={k:v for k,v in receipt.items() if k!='created_utc'},
                'Existing finalization receipt differs; preserved')
    else:
        atomic(output,encoded(receipt))
    print('Stage10Finalize=LOCAL_COMPLETE_SSH_PUSH_PENDING',flush=True)
    print('Stage10Commit='+head,flush=True)
    print('Stage10AnnotatedTag='+TAG,flush=True)
    print('Stage10FinalizationReceipt='+str(output),flush=True)
    print('Stage10NewPPOUpdates=0; Cloud=OFF_CONFIRMED_BY_USER; preserve cloud data',flush=True)
    print('Stage10Next=Run the following on the laptop:',flush=True)
    print('cd /home/lx/microduck-double-balance/workspace')
    print('git push origin double-balance')
    print('git push origin stage-10-complete')
    print('Normal successful SSH output is sufficient; do not repeat full remote verification.')
    return head

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--verify-only',action='store_true')
    args=parser.parse_args()
    payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    if args.verify_only:
        perform(payload,True)
    else:
        import fcntl
        lock=Path(tempfile.gettempdir())/('microduck-stage10-finalize-'+hashlib.sha256(str(REPO).encode()).hexdigest()[:16]+'.lock')
        fd=os.open(lock,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
        with os.fdopen(fd,'w') as f:
            try: fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError: raise RuntimeError('Another Stage 10 finalizer is running; no concurrent execution')
            perform(payload,False)

if __name__=='__main__':
    try: main()
    except Exception as error:
        print('Stage10Finalize=STOPPED; '+type(error).__name__+': '+str(error),flush=True)
        raise SystemExit(1)
